public abstract class UPSPricingRuleBuilder extends RunBase
{
    protected UPSPricingAttributeSourceLevel sourceLevel;
    protected Common masterRecord;
    protected UPSPricingRule pricingRule;

    protected boolean dialogOk = true;

}

Method.Source:
/// <summary>
/// This method init a master record which should later on link an <c>UPSPricingRule</c> record on it.
/// </summary>
public abstract void initMasterRecord()
{
}

/// <summary>
/// This method link created <c>UPSPricingRule</c> to master record.
/// </summary>
/// <param name = "_pricingRule">The <c>UPSPricingRule</c> to be linked.</param>
public abstract void linkPricingRule(UPSPricingRule _pricingRule)
{
}

/// <summary>
/// Create and return the master record linked with generated <c>UPSPricingRule</c>.
/// </summary>
/// <returns>The master record.</returns>
public final Common createRecord()
{
    this.run();

    return this.masterRecord;
}

public final void run()
{
    this.initMasterRecord();

    if (dialogOk)
    {
        ttsbegin;

        pricingRule.insert();
        this.linkPricingRule(pricingRule);

        if (dialogOk)
        {
            masterRecord.selectForUpdate(true);
            masterRecord.write();
        }
        else
        {
            pricingRule.delete();
        }

        ttscommit;

        UPSPricingRule rule = this.selectPriceAttributeGroup(this.sourceLevel);

        if (rule)
        {
            if (!masterRecord.validateWrite() && !rule.validateWrite())
            {
                error(strFmt("@UnifiedPricingService:UPSPricingRuleBuilder_RecordNotValid", masterRecord.RecId));
            }
        }
        else
        {
            warning("@UnifiedPricingService:UPSPricingRuleBuilder_FailToGeneratePricingRule");

            ttsbegin;

            rule.selectForUpdate(true);
            rule.delete();

            ttscommit;
        }
    }
}

private UPSPricingRule selectPriceAttributeGroup(UPSPricingAttributeSourceLevel _sourceLevel)
{
    xArgs args = new Args();

    Form createRuleForm = new Form(formStr(UPSAddPriceAttributeGroup));
    args.object(createRuleForm);
    args.parmEnumType(enumNum(UPSPricingAttributeSourceLevel));
    args.parmEnum(enum2int(_sourceLevel));
    args.record(this.pricingRule);

    FormRun addPriceAttributeGrp = ClassFactory.formRunClass(args);

    addPriceAttributeGrp.init();
    addPriceAttributeGrp.run();
    addPriceAttributeGrp.wait();

    UPSPricingRule rule;

    if (formHasMethod(addPriceAttributeGrp, identifierStr(masterRecord)))
    {
        rule = addPriceAttributeGrp.masterRecord() as UPSPricingRule;
    }

    return rule;
}

/// <summary>
/// Construct a dialog that can be used in method createMasterRecord or linkPricingRule
/// </summary>
/// <returns>The dialog object.</returns>
public Object dialog()
{
    return super();
}

/// <summary>
/// Get control values from dialog that can be used in method createMasterRecord or linkPricingRule
/// </summary>
/// <returns>True if Ok clicked; otherwise false.</returns>
public boolean getFromDialog()
{
    return super();
}
